import matplotlib.pyplot as plt

def plot_rl_curve():
    print("=== Generating RL Reward Curve Visualization ===")
    try:
        # Read the reward history generated by the swarm
        with open("rl_reward_curve.txt", "r") as f:
            rewards = [float(line.strip()) for line in f.readlines()]
        
        turns = list(range(1, len(rewards) + 1))
        
        plt.figure(figsize=(10, 6))
        
        # Plot the main reward line
        plt.plot(turns, rewards, linestyle='-', color='#2c3e50', linewidth=2.5, label="Cumulative RL Reward")
        
        # Add a baseline reference at Y=0
        plt.axhline(0, color='#e74c3c', linestyle='--', linewidth=1.5, label="Baseline (0.0)")
        
        # Formatting for publication quality
        plt.title("Metacognitive RL Reward Trajectory Over 100 Autonomous Turns", fontsize=14, fontweight='bold', pad=15)
        plt.xlabel("Agent Turn (Temporal Sequence)", fontsize=12)
        plt.ylabel("Cumulative Reward Score", fontsize=12)
        plt.grid(True, linestyle=':', alpha=0.7)
        plt.legend(loc="upper left")
        
        plt.tight_layout()
        plt.savefig("rl_reward_figure.png", dpi=300)
        print("[+] Graph successfully saved as 'rl_reward_figure.png' (300 DPI for publication)")
        
    except FileNotFoundError:
        print("[!] Error: 'rl_reward_curve.txt' not found. Run the swarm script first.")
    except Exception as e:
        print(f"[!] Error plotting graph: {e}")

if __name__ == "__main__":
    plot_rl_curve()
